SELECT '099.861.463-72' CPF, '30/07/2026' DATA_OBITO FROM DUAL 
)
SELECT
    S.*
FROM
    (
    SELECT
        E.SIGLA ORGAO,
        FO.CHAVE_FOLHA,
        FF.ID_PENSIONISTA,
        FF.ID_FUNCIONARIO,
        FF.ID_FOLHA_FUNCIONARIO,
        PDC.CPF_PESSOA CPF,
        HN.NOME,
        CO.ID_CERTIDAO_OBITO,
        NVL(FF.MATR_DEPENDENTE, FF.COD_INSTITUCIONAL) MATRICULA,
        FF.IND_REMUNERACAO,
        PD.NOME_DIVISAO,
        PS.NOME_SITUACAO,
        TF.NOME_TIPO_FUNCIONARIO,
        'UPDATE SW_PUBLICO.PESSOA SET DATA_OBITO = ''' || O.DATA_OBITO || ''' WHERE ID_PESSOA = ' || PDC.ID_PESSOA || ';' UPDATE_,
        'INSERT INTO SW_PUBLICO.PESSOA_CERTIDAO_OBITO (ID_CERTIDAO_OBITO, ID_PESSOA, DATA_OBITO, ID_ENTIDADE_EXTERNA, OFICIAL_TITULAR, DATA_CADASTRO) VALUES (SW_PUBLICO.SQ_PK_OBITO_PESSOA.NEXTVAL, ' || PDC.ID_PESSOA || ', ''' || O.DATA_OBITO || ''', 1003900, ''DATA ÓBITO EXTRAÍDA DA API DATAPREV'', ''' || SYSDATE || ''');' INSERT_1,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN 'UPDATE SW_ADAPI.FOLHA_FUNC SET IND_REMUNERACAO = ''N'' WHERE ID_FOLHA_FUNCIONARIO = ' || FF.ID_FOLHA_FUNCIONARIO || ';'
            ELSE 'FOLHA FECHADA'
        END UPDATE_1,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN 'DELETE FROM SW_ADAPI.FOLHA_FUNC_RUBRICA WHERE ID_FOLHA_FUNCIONARIO = ' || FF.ID_FOLHA_FUNCIONARIO || ';'
            ELSE 'FOLHA FECHADA'
        END DELETE_2,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN 'DELETE FROM SW_PUBLICO.FOLHA_BASE_UNICA_IMPOSTO WHERE ID_FOLHA = ' || FO.ID_FOLHA || ' AND ID_FOLHA_FUNCIONARIO = ' || FF.ID_FOLHA_FUNCIONARIO || ' AND ID_FUNCIONARIO = ' || FF.ID_FUNCIONARIO || ' AND ID_EMPRESA = ' || E.ID_EMPRESA || ';'
            ELSE 'FOLHA FECHADA'
        END DELETE_B,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN
                CASE
                    WHEN PC.ID_PENSIONISTA IS NULL THEN 'UPDATE SW_ADAPI.FUNCIONARIO_PERFIL SET DATA_FIM = ''31/08/2026'' WHERE ID_FUNCIONARIO_PERFIL = ' || FP.ID_FUNCIONARIO_PERFIL || ';'
                END
            ELSE 'FOLHA FECHADA'
        END UPDATE_3,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN 
                CASE
                    WHEN PC.ID_PENSIONISTA IS NULL  THEN 'INSERT INTO SW_ADAPI.FUNCIONARIO_PERFIL (ID_FUNCIONARIO_PERFIL, ID_FUNCIONARIO, ID_PERFIL, ID_MOVIMENTACAO, ID_TIPO_FUNCIONARIO, ID_ESB_CATEG_TRABALHADOR, ID_TIPO_INCIDENCIA, IND_PERMITE_ALTERAR, ID_REMUNERACAO, DATA_CADASTRO, DATA_INICIO, OBSERVACAO) VALUES (SW_ADAPI.SQ_PK_FUNCIONARIO_PERFIL.NEXTVAL, ' || FF.ID_FUNCIONARIO || ', ' || (SELECT ID_PERFIL FROM SW_ADAPI.RHB_PERFIL WHERE ID_DIVISAO = PD.ID_DIVISAO AND ID_SITUACAO = 1000001) || ', 8, ' || FP.ID_TIPO_FUNCIONARIO || ', ' || NVL(TO_CHAR(FP.ID_ESB_CATEG_TRABALHADOR), 'NULL') || ', ' || FP.ID_TIPO_INCIDENCIA || ', ''' || FP.IND_PERMITE_ALTERAR || ''', 2, ''' || SYSDATE || ''', ''01/09/2026'', ''DATA ÓBITO EXTRAÍDA DA API DATAPREV'');'
                END
