        LEFT JOIN SW_PUBLICO.PESSOA_CERTIDAO_OBITO CO ON CO.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO)
        LEFT JOIN SW_ADAPI.FUNC_PENSAO_CIVIL PC ON PC.ID_PENSIONISTA = FF.ID_PENSIONISTA AND PC.DATA_FIM IS NULL
        LEFT JOIN SW_ADAPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
        LEFT JOIN SW_ADAPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
        LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
        LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
        LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO TF ON TF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
        JOIN OBITOS O ON O.CPF = PDC.CPF_PESSOA
        JOIN SW_PUBLICO.EMPRESA E ON E.SIGLA = 'ADAPI'
    WHERE
        FO.MES = 9
        AND FO.ANO = 2026
        AND PDC.CPF_PESSOA IN ('133.116.033-20','105.409.463-20','145.172.053-04','036.166.303-04','078.292.053-53','152.417.003-82','186.062.103-15','217.101.203-04','151.698.713-68','003.182.993-72','256.225.951-34','246.885.253-20','181.441.873-34','077.503.583-15','047.507.133-68','156.383.913-04','161.133.143-91','097.032.763-34','130.964.513-20','043.620.983-72','099.470.603-06','007.556.803-91','152.983.883-53','130.850.183-87','079.292.503-34','185.624.693-00','077.164.603-82','067.116.263-20','218.370.903-00','077.884.363-72','011.058.253-53','133.457.453-72','273.774.233-15','096.498.593-49','096.041.623-49','130.148.383-49','132.467.803-82','226.230.353-34','025.778.013-00','287.427.373-20','226.389.203-63','095.926.283-00','039.362.563-06','160.339.653-53','138.490.693-20','036.128.133-15','152.055.843-00','184.319.173-34','182.655.373-87','129.901.833-53','209.853.713-15','011.396.303-34','007.410.003-34','151.580.473-91','227.838.653-00','099.861.463-72')
        AND FF.IND_REMUNERACAO = 'S'
