        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN 'UPDATE SW_ADH.FOLHA_FUNC SET IND_REMUNERACAO = ''N'' WHERE ID_FOLHA_FUNCIONARIO = ' || FF.ID_FOLHA_FUNCIONARIO || ';'
            ELSE 'FOLHA FECHADA'
        END UPDATE_1,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN 'DELETE FROM SW_ADH.FOLHA_FUNC_RUBRICA WHERE ID_FOLHA_FUNCIONARIO = ' || FF.ID_FOLHA_FUNCIONARIO || ';'
            ELSE 'FOLHA FECHADA'
        END DELETE_2,
