                CASE
                    WHEN PC.ID_PENSIONISTA IS NULL  THEN 'INSERT INTO SW_ADH.FUNCIONARIO_PERFIL (ID_FUNCIONARIO_PERFIL, ID_FUNCIONARIO, ID_PERFIL, ID_MOVIMENTACAO, ID_TIPO_FUNCIONARIO, ID_ESB_CATEG_TRABALHADOR, ID_TIPO_INCIDENCIA, IND_PERMITE_ALTERAR, ID_REMUNERACAO, DATA_CADASTRO, DATA_INICIO, OBSERVACAO) VALUES (SW_ADH.SQ_PK_FUNCIONARIO_PERFIL.NEXTVAL, ' || FF.ID_FUNCIONARIO || ', ' || (SELECT ID_PERFIL FROM SW_ADH.RHB_PERFIL WHERE ID_DIVISAO = PD.ID_DIVISAO AND ID_SITUACAO = 1000001) || ', 8, ' || FP.ID_TIPO_FUNCIONARIO || ', ' || NVL(TO_CHAR(FP.ID_ESB_CATEG_TRABALHADOR), 'NULL') || ', ' || FP.ID_TIPO_INCIDENCIA || ', ''' || FP.IND_PERMITE_ALTERAR || ''', 2, ''' || SYSDATE || ''', ''01/09/2026'', ''DATA ÓBITO EXTRAÍDA DA API DATAPREV'');'
                END
            ELSE 'FOLHA FECHADA'
        END INSERT_2,
        CASE
            WHEN PC.ID_PENSIONISTA IS NOT NULL THEN 'UPDATE SW_ADH.FUNC_PENSAO_CIVIL SET DATA_FIM = ''31/08/2026'' WHERE ID_PENSIONISTA = ' || PC.ID_PENSIONISTA || ';'
        END UP_PEN
    FROM
        SW_ADH.FOLHA FO
        JOIN SW_ADH.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_PUBLICO.PESSOA_DOC_CPF PDC ON PDC.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO) AND PDC.DATA_BAIXA IS NULL
        JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO) AND HN.DATA_FIM IS NULL
        LEFT JOIN SW_PUBLICO.PESSOA_CERTIDAO_OBITO CO ON CO.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO)
        LEFT JOIN SW_ADH.FUNC_PENSAO_CIVIL PC ON PC.ID_PENSIONISTA = FF.ID_PENSIONISTA AND PC.DATA_FIM IS NULL
        LEFT JOIN SW_ADH.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
        LEFT JOIN SW_ADH.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
        LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
        LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
        LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO TF ON TF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
        JOIN OBITOS O ON O.CPF = PDC.CPF_PESSOA
        JOIN SW_PUBLICO.EMPRESA E ON E.SIGLA = 'ADH'
    WHERE
        FO.MES = 9
        AND FO.ANO = 2026
        AND PDC.CPF_PESSOA IN ('133.116.033-20','105.409.463-20','145.172.053-04','036.166.303-04','078.292.053-53','152.417.003-82','186.062.103-15','217.101.203-04','151.698.713-68','003.182.993-72','256.225.951-34','246.885.253-20','181.441.873-34','077.503.583-15','047.507.133-68','156.383.913-04','161.133.143-91','097.032.763-34','130.964.513-20','043.620.983-72','099.470.603-06','007.556.803-91','152.983.883-53','130.850.183-87','079.292.503-34','185.624.693-00','077.164.603-82','067.116.263-20','218.370.903-00','077.884.363-72','011.058.253-53','133.457.453-72','273.774.233-15','096.498.593-49','096.041.623-49','130.148.383-49','132.467.803-82','226.230.353-34','025.778.013-00','287.427.373-20','226.389.203-63','095.926.283-00','039.362.563-06','160.339.653-53','138.490.693-20','036.128.133-15','152.055.843-00','184.319.173-34','182.655.373-87','129.901.833-53','209.853.713-15','011.396.303-34','007.410.003-34','151.580.473-91','227.838.653-00','099.861.463-72')
        AND FF.IND_REMUNERACAO = 'S'
    UNION ALL
    SELECT
        E.SIGLA ORGAO,
        FO.CHAVE_FOLHA,
        FF.ID_PENSIONISTA,
        FF.ID_FUNCIONARIO,
        FF.ID_FOLHA_FUNCIONARIO,
        PDC.CPF_PESSOA CPF,
        HN.NOME,
        CO.ID_CERTIDAO_OBITO,
        NVL(FF.MATR_DEPENDENTE, FF.COD_INSTITUCIONAL) MATRICULA,
        FF.IND_REMUNERACAO,
        PD.NOME_DIVISAO,
        PS.NOME_SITUACAO,
        TF.NOME_TIPO_FUNCIONARIO,
        'UPDATE SW_PUBLICO.PESSOA SET DATA_OBITO = ''' || O.DATA_OBITO || ''' WHERE ID_PESSOA = ' || PDC.ID_PESSOA || ';' UPDATE_,
        'INSERT INTO SW_PUBLICO.PESSOA_CERTIDAO_OBITO (ID_CERTIDAO_OBITO, ID_PESSOA, DATA_OBITO, ID_ENTIDADE_EXTERNA, OFICIAL_TITULAR, DATA_CADASTRO) VALUES (SW_PUBLICO.SQ_PK_OBITO_PESSOA.NEXTVAL, ' || PDC.ID_PESSOA || ', ''' || O.DATA_OBITO || ''', 1003900, ''DATA ÓBITO EXTRAÍDA DA API DATAPREV'', ''' || SYSDATE || ''');' INSERT_1,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN 'UPDATE SW_AGESPISA.FOLHA_FUNC SET IND_REMUNERACAO = ''N'' WHERE ID_FOLHA_FUNCIONARIO = ' || FF.ID_FOLHA_FUNCIONARIO || ';'
            ELSE 'FOLHA FECHADA'
        END UPDATE_1,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN 'DELETE FROM SW_AGESPISA.FOLHA_FUNC_RUBRICA WHERE ID_FOLHA_FUNCIONARIO = ' || FF.ID_FOLHA_FUNCIONARIO || ';'
            ELSE 'FOLHA FECHADA'
        END DELETE_2,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN 'DELETE FROM SW_PUBLICO.FOLHA_BASE_UNICA_IMPOSTO WHERE ID_FOLHA = ' || FO.ID_FOLHA || ' AND ID_FOLHA_FUNCIONARIO = ' || FF.ID_FOLHA_FUNCIONARIO || ' AND ID_FUNCIONARIO = ' || FF.ID_FUNCIONARIO || ' AND ID_EMPRESA = ' || E.ID_EMPRESA || ';'
            ELSE 'FOLHA FECHADA'
        END DELETE_B,
